=== SIDENAV TS ===
import { animate, keyframes, style, transition, trigger } from '@angular/animations';
import { CommonModule } from '@angular/common';
import {
  Component,
  ElementRef,
  EventEmitter,
  HostListener,
  OnDestroy,
  OnInit,
  Output,
} from '@angular/core';
import {
  Router,
  RouterLink,
  RouterLinkActive,
  NavigationEnd,
  IsActiveMatchOptions,
} from '@angular/router'; // Import NavigationEnd
import { fadeInOut } from './helper';
import { TreeViewComponent } from '../tree-view/tree-view.component';
import { AuthService } from '../../services/auth.service';
import { DxButtonModule, DxPopupModule } from 'devextreme-angular';
import { Subscription, filter } from 'rxjs'; // Import filter
import { buildNavTree, normalizeMenuRecord } from './menu-tree';
import { decryptData } from '../../services/utils';

@Component({
  selector: 'app-sidenav',
  standalone: true,
  templateUrl: './sidenav.component.html',
  styleUrl: './sidenav.component.scss',
  animations: [
    fadeInOut,
    trigger('rotate', [
      transition(':enter', [
        animate(
          '1000ms',
          keyframes([
            style({ transform: 'rotate(0deg)', offset: '0' }),
            style({ transform: 'rotate(2turn)', offset: '1' }),
          ]),
        ),
      ]),
    ]),
  ],
  imports: [
    CommonModule,
    RouterLink,
    RouterLinkActive,
    TreeViewComponent,
    DxPopupModule,
    DxButtonModule,
  ],
})
export class SidenavComponent implements OnInit, OnDestroy {
  @Output() onToggleSideNav: EventEmitter<any> = new EventEmitter();
  collapsed = true;
  screenWidth = 0;
  commonData: any[] = [];
  multiple: boolean = false;
  userEmail = localStorage.getItem('email');
  organization_name: any;
  showDropdown = false;
  showLogoutDialog = false;
  _ScreenName: string = '';
  username: string = 'User';
  showNotifications = false;
  readonly linkActiveMatchOptions: IsActiveMatchOptions = {
    paths: 'subset',
    queryParams: 'ignored',
    matrixParams: 'ignored',
    fragment: 'ignored',
  };
  private subscription: Subscription = new Subscription();
  @HostListener('window:resize', ['$event'])
  onResize(event: any) {
    this.screenWidth = window.innerWidth;
    if (this.screenWidth <= 768) {
      this.collapsed = false;
    }
    this.onToggleSideNav.emit({
      collapsed: this.collapsed,
      screenWidth: this.screenWidth,
    });
  }
  constructor(
    public router: Router,
    private elementRef: ElementRef,
    private authService: AuthService,
  ) {
    this.subscription.add(
      this.router.events.pipe(filter((event) => event instanceof NavigationEnd)).subscribe(() => {
        this.updateMenuState();
      }),
    );
    this.subscription.add(
      this.authService.menusUpdated$.subscribe(() => {
        this.refreshMenu();
      }),
    );
  }
  @HostListener('document:click', ['$event'])
  onDocumentClick(event: MouseEvent) {
    if (!this.elementRef.nativeElement.contains(event.target)) {
      this.showDropdown = false;
      this.showNotifications = false;
    }
  }
  ngOnInit(): void {
    this.screenWidth = window.innerWidth;
    this.username = localStorage.getItem('userName') || 'User';
    if (this.screenWidth <= 768) {
      this.collapsed = false;
    }
    this.onToggleSideNav.emit({
      collapsed: this.collapsed,
      screenWidth: this.screenWidth,
    });
    this.subscription.add(
      this.authService.screenName$.subscribe((name) => {
        this._ScreenName = name;
      }),
    );
    this.refreshMenu();
  }

  /**
   * Paint from the cached folder tree first, then refresh it in the background and repaint.
   *
   * Painting first matters: the tree is a network round-trip away and the sidebar must not sit
   * empty until it lands. On a first-ever login the cache is empty, so the first paint groups by
   * ParentMenu alone and the repaint a moment later adds the tree's ordering and icons.
   */
  private refreshMenu(): void {
    this.buildDynamicMenu();
    this.updateMenuState();

    void this.authService.loadMenuGroups().then((changed) => {
      if (!changed) {
        return;
      }
      this.buildDynamicMenu();
      this.updateMenuState();
    });
  }

  /**
   * Rebuilds the sidebar from the menus this user is entitled to and the folder tree those
   * screens are grouped into.
   *
   * All of the grouping logic lives in menu-tree.ts, which is a port of the sibling hr_payroll
   * project's Payroll.master.cs - both apps read the same HR_MenuGroups / HR_MenuItems tables,
   * so the two navigations stay identical by construction. This method is only the plumbing.
   */
  private buildDynamicMenu(): void {
    try {
      if (!this.authService.isLoggedIn()) {
        this.commonData = [];
        return;
      }

      const storedMenusStr = localStorage.getItem('menus');
      if (!storedMenusStr) {
        this.commonData = [];
        return;
      }

      const flatMenus = decryptData(storedMenusStr);
      if (!Array.isArray(flatMenus)) {
        this.commonData = [];
        return;
      }

      const normalizedMenus = flatMenus
        .map((menu) => normalizeMenuRecord(menu))
        .filter((menu) => !!menu.navigateUrl);

      normalizedMenus.sort((a, b) => (a.displayOrder || 0) - (b.displayOrder || 0));

      const menuMap = new Map<string, any>();
      const rootItems: any[] = [];
      const parentGroups: any[] = [];

      normalizedMenus.forEach((menu) => {
        const menuItem = {
          label: menu.mainMenuText || menu.mainMenu || 'Menu',
          routeLink:
            menu.navigateUrl && !menu.navigateUrl.startsWith('http') ? menu.navigateUrl : undefined,
          url:
            menu.navigateUrl && menu.navigateUrl.startsWith('http') ? menu.navigateUrl : undefined,
          icon: menu.menuIcon || '',
          target: menu.navigateUrl && menu.navigateUrl.startsWith('http') ? '_blank' : undefined,
          items: [] as any[],
        };

        if (!menu.parentMenu || menu.parentMenu.trim() === '') {
          rootItems.push(menuItem);
        } else {
          if (!menuMap.has(menu.parentMenu)) {
            const parentNode = {
              label: menu.parentMenu,
              icon: menu.parentMenuIcon || 'fa-solid fa-folder',
              expanded: false,
              items: [] as any[],
            };
            menuMap.set(menu.parentMenu, parentNode);
            parentGroups.push(parentNode);
          }
          menuMap.get(menu.parentMenu).items.push(menuItem);
        }
      });

      this.commonData = [...rootItems, ...parentGroups];
    } catch (e) {
      console.error('Failed to build the dynamic menu', e);
      this.commonData = [];
    }
    // this.commonData = buildNavTree(
    //   this.authService.getMenus(),
    //   this.authService.getMenuGroups(),
    // );
  }

  private isRouteLinkActive(routeLink: string): boolean {
    if (!routeLink) {
      return false;
    }
    return this.router.isActive(routeLink, this.linkActiveMatchOptions);
  }

  private isExternalUrlActive(url: string): boolean {
    if (!url) {
      return false;
    }
    try {
      const tree = this.router.parseUrl(this.router.url);
      const path =
        '/' + (tree.root.children['primary']?.segments.map((s) => s.path).join('/') ?? '');
      return path === url || this.router.url.includes(url);
    } catch {
      return this.router.url.includes(url);
    }
  }
  private updateMenuState(): void {
    this.commonData.forEach((item) => this.collapseAll(item));
    this.commonData.forEach((item) => this.setExpansionState(item));
  }
  private collapseAll(item: any): void {
    item.expanded = false;
    if (item.items && item.items.length > 0) {
      item.items.forEach((child: any) => this.collapseAll(child));
    }
  }
  private setExpansionState(item: any): boolean {
    if (item.routeLink && this.isRouteLinkActive(item.routeLink)) {
      return true;
    }
    if (item.url && this.isExternalUrlActive(item.url)) {
      return true;
    }
    if (item.items && item.items.length > 0) {
      let anyChildActive = false;
      for (const child of item.items) {
        if (this.setExpansionState(child)) {
          anyChildActive = true;
          break;
        }
      }
      if (anyChildActive) {
        item.expanded = true;
        return true;
      }
    }
    return false;
  }
  toggleCollapse(): void {
    if (this.screenWidth <= 768) {
      this.collapsed = false;
    } else {
      this.collapsed = !this.collapsed;
    }
    this.onToggleSideNav.emit({
      collapsed: this.collapsed,
      screenWidth: this.screenWidth,
    });
  }
  closeSidenav(): void {
    this.collapsed = false;
    this.onToggleSideNav.emit({
      collapsed: this.collapsed,
      screenWidth: this.screenWidth,
    });
  }
  handleClick(item: any): void {
    if (!this.multiple) {
      for (const modelItem of this.commonData) {
        if (item !== modelItem && modelItem.expanded) {
          modelItem.expanded = false;
        }
      }
    }
    item.expanded = !item.expanded;
  }
  shrinkItems(item: any): void {
    if (item.routeLink && (!item.items || item.items.length === 0)) {
      this.collapsed = true;
      this.onToggleSideNav.emit({
        collapsed: this.collapsed,
        screenWidth: this.screenWidth,
      });
    }
    if (!this.multiple) {
      for (const modelItem of this.commonData) {
        if (item !== modelItem && modelItem.expanded) {
          modelItem.expanded = false;
        }
      }
    }
  }
  getActiveClass(item: any): string {
    if (item.routeLink && this.isRouteLinkActive(item.routeLink)) {
      return 'active-sublevel';
    }
    if (item.url && this.isExternalUrlActive(item.url)) {
      return 'active-sublevel';
    }
    if (item.items && item.items.length > 0) {
      if (this.hasActiveChild(item)) {
        return 'active-parent';
      }
    }
    return '';
  }
  hasActiveChild(item: any): boolean {
    if (item.routeLink && this.isRouteLinkActive(item.routeLink)) {
      return true;
    }
    if (item.url && this.isExternalUrlActive(item.url)) {
      return true;
    }
    if (item.items && item.items.length > 0) {
      return item.items.some((child: any) => this.hasActiveChild(child));
    }
    return false;
  }
  private isAnyChildActive(item: any): boolean {
    if (item.routeLink && this.isRouteLinkActive(item.routeLink)) {
      return true;
    } else if (item.url && this.isExternalUrlActive(item.url)) {
      return true;
    }
    if (item.items && item.items.length > 0) {
      return item.items.some((child: any) => this.isAnyChildActive(child));
    }
    return false;
  }
  logout() {
    this.showLogoutDialog = false;
    this.authService.logOut();
  }
  confirmLogout() {
    this.logout();
  }
  onDialogHiding() {
    this.showLogoutDialog = false;
  }
  toggleDropdown(event: Event) {
    event.stopPropagation();
    this.showDropdown = !this.showDropdown;
  }
  ngOnDestroy(): void {
    this.subscription.unsubscribe();
  }
  toggleNotification() {
    this.showNotifications = !this.showNotifications;
  }
  notifications: string[] = [
    'New user registered',
    'Server maintenance at 6 PM',
    'New report available',
  ];
}

