=== TS ===
import { Component, EventEmitter, Input, OnChanges, Output, SimpleChanges, ViewChild } from '@angular/core';
import { firstValueFrom, isObservable, Observable } from 'rxjs';
import { DxDataGridComponent, DxDataGridModule, DxPopupModule, DxButtonModule } from 'devextreme-angular';
import { RouterModule } from '@angular/router';
import { CommonModule } from '@angular/common';
import * as ExcelJS from 'exceljs';
import { saveAs } from 'file-saver';
import { exportDataGrid } from 'devextreme/excel_exporter';

type SummaryItem = {
  column: string;
  summaryType: 'sum' | 'min' | 'max' | 'avg' | 'count' | 'custom';
  valueFormat?: string;
};

/**
 * "Job Code", not "JOB CODE" or "job code" — every column header goes through
 * this regardless of how its caption was written. Handles camelCase/snake_case/
 * kebab-case captions too (inserts the word break before re-casing), so a
 * caption that was never spaced out to begin with still comes out right.
 */
function toTitleCase(text: string): string {
  if (!text) return text;
  const spaced = text.replace(/([a-z])([A-Z])/g, '$1 $2').replace(/[_-]+/g, ' ');
  return spaced
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => word[0].toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
}

/** Recurses into a buttons column's own `caption`, but leaves per-button `text`/`hint` alone — those are actions, not headers. */
function titleCaseColumn(column: any): any {
  if (!column || typeof column !== 'object') return column;
  return column.caption ? { ...column, caption: toTitleCase(column.caption) } : column;
}

@Component({
  selector: 'app-common-grid',
  templateUrl: './common-grid.component.html',
  styleUrls: ['./common-grid.component.scss'],
  imports: [DxDataGridModule, RouterModule, CommonModule, DxPopupModule, DxButtonModule],
})
export class CommonGridComponent implements OnChanges {
  @Input() dataSource: unknown[] = [];
  @Input() columns: any[] = [];

  /**
   * What the grid actually renders — headers title-cased regardless of how
   * the caller wrote them. A plain property recomputed only when `columns`
   * itself changes, NOT a getter: a getter hands dx-data-grid a brand-new
   * array reference on every single change-detection pass, and DevExtreme
   * reads that as "the columns changed" and keeps resetting the grid —
   * which can leave it stuck mid-initialization and never actually render,
   * even once the data has arrived.
   */
  titleCasedColumns: any[] = [];

  /**
   * Same rule as `titleCasedColumns`: a plain property rebuilt in ngOnChanges,
   * never a getter or a template literal that depends on a method call.
   */
  editingConfig: Record<string, unknown> = {};

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['columns']) {
      this.titleCasedColumns = this.columns.map((col) => titleCaseColumn(col));
    }
    this.editingConfig = this.buildEditingConfig();
  }

  private buildEditingConfig(): Record<string, unknown> {
    if (this.inlineEditing) {
      // 'cell' mode = every cell saves on blur (one updateFn call per edit).
      return {
        mode: 'cell',
        allowUpdating: this.allowRowEdit && !!this.updateFn,
        allowAdding: !!this.insertFn,
        allowDeleting: this.allowRowDelete,
        useIcons: true,
        confirmDelete: false,
      };
    }
    return {
      mode: 'row',
      allowUpdating: this.allowRowEdit,
      allowAdding: false,
      allowDeleting: this.allowRowDelete,
      useIcons: true,
      confirmDelete: false,
    };
  }
  @Input() storageKey = 'commonGridStorage';
  @Input() summaryItems: SummaryItem[] = [];
  @Input() showAddButton = false;
  @Input() addButtonText = 'Add';
  @Input() gridTitle = '';
  @Input() gridIcon = '';
  /** Optional line under the title (e.g. record count or short help text). */
  @Input() gridSubtitle = '';
  /** Default: wrap cell text to fit viewport; widen columns to trigger horizontal scroll on host. */
  @Input() wordWrapEnabled = true;
  @Input() columnAutoWidth = true;
  /** When true, columns hide on narrow viewports instead of horizontal scroll. */
  @Input() columnHidingEnabled = true;
  /** True = grid fills parent height (Travel Policy pattern — pager visible at bottom). */
  @Input() fillViewport = true;
  @Input() showGroupPanel = false;
  @Input() showRefreshButton = false;
  @Input() refreshDisabled = false;
  /** When false, use custom action columns only (no row edit icon). */
  @Input() allowRowEdit = true;
  /** When false, use custom delete or parent popup only. */
  @Input() allowRowDelete = true;
  @Input() exportFileName = 'UserData.xlsx';
  /** Persist column widths/order in localStorage (disable for fixed-width report grids). */
  @Input() enableStateStoring = true;
  readonly gridScrolling = {
    mode: 'standard' as const,
    columnRenderingMode: 'standard' as const,
    scrollByContent: true,
    showScrollbar: 'always' as const,
    useNative: true,
  };
  @Output() addRow = new EventEmitter<void>();
  @Output() refresh = new EventEmitter<void>();
  @Output() cellClick = new EventEmitter<any>();
  @Output() editRow = new EventEmitter<any>();
  @Output() deleteRow = new EventEmitter<any>();
  @Input() onCellPrepared?: (e: any) => void;
  @Input() onEditorPreparing?: (e: any) => void;

  /**
   * Opt-in inline editing: every cell saves on blur through the callbacks below.
   * Off by default, in which case the grid behaves exactly as before (edit icon
   * -> `editRow` -> parent opens a form).
   */
  @Input() inlineEditing = false;
  /** Row key field. Leave unset for grids that don't edit inline. Needed for reliable updates when `inlineEditing` is on. */
  @Input() keyExpr?: string;
  /** Called once per saved cell. Reject/throw to revert the cell (parent shows the toast). `changes` = only the edited fields; `fullRow` = old row merged with changes. */
  @Input() updateFn?: (key: any, changes: any, fullRow: any) => Observable<unknown> | Promise<unknown>;
  @Input() insertFn?: (row: any) => Observable<unknown> | Promise<unknown>;
  /** Called after the delete confirm popup. When unset, `deleteRow` is emitted as before. */
  @Input() deleteFn?: (row: any) => Observable<unknown> | Promise<unknown>;
  /** Per-cell lock, e.g. a Group row can't edit "Box Type". Return false to block the edit. */
  @Input() isCellEditable?: (row: any, dataField: string) => boolean;

  @ViewChild(DxDataGridComponent) private dataGrid?: DxDataGridComponent;

  isDeletePopupVisible = false;
  selectedRowForDelete: any = null;
  onAddClick(): void {
    if (this.inlineEditing && this.insertFn) {
      this.dataGrid?.instance.addRow();
      return;
    }
    this.addRow.emit();
  }

  /**
   * DevExtreme cancels the edit when `e.cancel` resolves to true. A failed save
   * resolves true (instead of rejecting, which would also paint DevExtreme's own
   * error row on top of the parent's toast) and then drops the pending edit so
   * the cell shows its old value again.
   */
  private runSave(e: any, call: () => Observable<unknown> | Promise<unknown>): void {
    e.cancel = (async () => {
      try {
        const result = call();
        await (isObservable(result) ? firstValueFrom(result) : result);
        return false;
      } catch {
        e.component.cancelEditData();
        return true;
      }
    })();
  }

  onRowUpdating(e: any): void {
    if (!this.inlineEditing || !this.updateFn) return;
    const fn = this.updateFn;
    this.runSave(e, () => fn(e.key, e.newData, { ...e.oldData, ...e.newData }));
  }

  onRowInserting(e: any): void {
    if (!this.inlineEditing || !this.insertFn) return;
    const fn = this.insertFn;
    this.runSave(e, () => fn(e.data));
  }
  async onExporting(e: any): Promise<void> {
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet('User Data');
    await exportDataGrid({
      component: e.component,
      worksheet,
      autoFilterEnabled: true,
    });
    const buffer = await workbook.xlsx.writeBuffer();
    saveAs(new Blob([buffer], { type: 'application/octet-stream' }), this.exportFileName);
    e.cancel = true;
  }
  onEditingStart(e: any): void {
    if (this.inlineEditing) {
      // Fires per cell in 'cell' mode; block locked cells, let the rest edit.
      const field = e.column?.dataField;
      if (this.isCellEditable && field && !this.isCellEditable(e.data, field)) e.cancel = true;
      return;
    }
    e.cancel = true;
    this.editRow.emit(e.data);
  }
  onRowRemoving(e: any): void {
    e.cancel = true;
    this.selectedRowForDelete = e.data;
    this.isDeletePopupVisible = true;
  }
  confirmDelete(): void {
    if (this.selectedRowForDelete) {
      if (this.inlineEditing && this.deleteFn) {
        const result = this.deleteFn(this.selectedRowForDelete);
        // Parent owns errors/toasts and the reload; swallow the rejection so it isn't unhandled.
        (isObservable(result) ? firstValueFrom(result) : result).catch(() => {});
      } else {
        this.deleteRow.emit(this.selectedRowForDelete);
      }
    }
    this.isDeletePopupVisible = false;
    this.selectedRowForDelete = null;
  }
  cancelDelete(): void {
    this.isDeletePopupVisible = false;
    this.selectedRowForDelete = null;
  }
}

